import { useMemo, useState } from 'react';
import { Button, Card, Stack, Text } from '@jinx-ui/react';

type ReportDatePickerProps = {
  value?: Date;
  onChange: (date: Date) => void;
};

const WEEKDAYS = ['Пн', 'Вт', 'Ср', 'Чт', 'Пт', 'Сб', 'Вс'];
const MONTHS = [
  'Январь', 'Февраль', 'Март', 'Апрель', 'Май', 'Июнь',
  'Июль', 'Август', 'Сентябрь', 'Октябрь', 'Ноябрь', 'Декабрь',
];

const startOfDay = (d: Date) => new Date(d.getFullYear(), d.getMonth(), d.getDate());

const addDays = (d: Date, amount: number) => {
  const next = startOfDay(d);
  next.setDate(next.getDate() + amount);
  return next;
};

const isSameDay = (a: Date, b: Date) =>
  a.getFullYear() === b.getFullYear() &&
  a.getMonth() === b.getMonth() &&
  a.getDate() === b.getDate();

function buildMonthCells(year: number, month: number): Array<Date | null> {
  const leadingBlanks = (new Date(year, month, 1).getDay() + 6) % 7;
  const daysInMonth = new Date(year, month + 1, 0).getDate();
  const cells: Array<Date | null> = new Array(leadingBlanks).fill(null);
  for (let day = 1; day <= daysInMonth; day += 1) {
    cells.push(new Date(year, month, day));
  }
  while (cells.length % 7 !== 0) {
    cells.push(null);
  }
  return cells;
}

export default function ReportDatePicker({ value, onChange }: ReportDatePickerProps) {
  const today = useMemo(() => startOfDay(new Date()), []);
  const [selected, setSelected] = useState<Date>(() => (value ? startOfDay(value) : today));
  const current = value ? startOfDay(value) : selected;
  const [viewDate, setViewDate] = useState<Date>(() => new Date(current.getFullYear(), current.getMonth(), 1));

  const cells = useMemo(
    () => buildMonthCells(viewDate.getFullYear(), viewDate.getMonth()),
    [viewDate],
  );

  const quickOptions = useMemo(
    () => [
      { label: 'Сегодня', date: today },
      { label: 'Вчера', date: addDays(today, -1) },
      { label: 'Неделя назад', date: addDays(today, -7) },
    ],
    [today],
  );

  const pick = (date: Date) => {
    setSelected(date);
    setViewDate(new Date(date.getFullYear(), date.getMonth(), 1));
    onChange(date);
  };

  const shiftMonth = (delta: number) =>
    setViewDate((prev) => new Date(prev.getFullYear(), prev.getMonth() + delta, 1));

  return (
    <Card>
      <Stack direction="vertical" gap="md">
        <Stack direction="horizontal" gap="sm" wrap>
          {quickOptions.map((option) => (
            <Button
              key={option.label}
              size="sm"
              variant={isSameDay(current, option.date) ? 'primary' : 'secondary'}
              onClick={() => pick(option.date)}
            >
              {option.label}
            </Button>
          ))}
        </Stack>

        <Stack direction="horizontal" gap="sm" align="center" justify="space-between">
          <Button size="sm" variant="ghost" aria-label="Предыдущий месяц" onClick={() => shiftMonth(-1)}>
            ←
          </Button>
          <Text weight="medium">
            {`${MONTHS[viewDate.getMonth()]} ${viewDate.getFullYear()}`}
          </Text>
          <Button size="sm" variant="ghost" aria-label="Следующий месяц" onClick={() => shiftMonth(1)}>
            →
          </Button>
        </Stack>

        <div
          role="grid"
          style={{
            display: 'grid',
            gridTemplateColumns: 'repeat(7, 1fr)',
            gap: 'var(--jx-space-xs)',
          }}
        >
          {WEEKDAYS.map((weekday) => (
            <Text key={weekday} size="sm" tone="muted" align="center">
              {weekday}
            </Text>
          ))}

          {cells.map((date, index) => {
            if (!date) {
              return <span key={`blank-${index}`} aria-hidden="true" />;
            }
            const isSelected = isSameDay(date, current);
            return (
              <Button
                key={date.toISOString()}
                size="sm"
                fullWidth
                variant={isSelected ? 'primary' : 'ghost'}
                aria-pressed={isSelected}
                onClick={() => pick(date)}
              >
                {date.getDate()}
              </Button>
            );
          })}
        </div>
      </Stack>
    </Card>
  );
}

